from torch import nn
class Model(nn.Module):
 def __init__(self):
  super().__init__()
  self.layer=nn.Linear(3,3,bias=False)
 def forward(self,x,flag):
  left=self.layer(x)
  right=self.layer(x)
  if flag:
   return left+right
  return left-right

